namespace Atc.Rest.Api.Generator.Cli.Tests.Extractors.TypeScript;

/// <summary>
/// Every generated TypeScript file starts with the auto-generated line the service recognises its own files by, and
/// then names the tool version that wrote it - what the C# output carries in <c>[GeneratedCode]</c>.
/// </summary>
public sealed class TypeScriptHeaderBuilderTests
{
    [Fact]
    public void FileHeader_IsTheAutoGeneratedLine_ThenTheToolVersion()
    {
        var lines = TypeScriptHeaderBuilder.FileHeader.Split('\n');

        Assert.Equal("// <auto-generated />", lines[0]);
        Assert.Equal("// atc-rest-api-gen " + GeneratorInfo.Version, lines[1]);
        Assert.Equal(string.Empty, lines[2]);
        Assert.StartsWith(TypeScriptHeaderBuilder.AutoGeneratedHeader, TypeScriptHeaderBuilder.FileHeader, StringComparison.Ordinal);
    }

    [Fact]
    public void AutoGeneratedHeader_IsTheFirstLineAlone()
        => Assert.Equal("// <auto-generated />\n", TypeScriptHeaderBuilder.AutoGeneratedHeader);
}